{
  "name": "ACQ400数据采集机箱",
  "name_en": "ACQ400 Data Acquisition Chassis",
  "manufacturer": "D-TACQ",
  "description": "ACQ400是一类模块化高速数据采集机箱，用于在实验中采集、监测并流式保存模拟量或数字量信号。它通常集成多个采集站点或插槽，可通过EPICS过程变量进行状态监控、参数访问和连续数据记录，适用于物理实验、工程测试和装置诊断。",
  "description_en": "The ACQ400 is a modular high-speed data acquisition chassis used in laboratories to acquire, monitor, and stream analog or digital signals to storage. It typically includes multiple acquisition sites or slots and is operated through EPICS process variables for status monitoring, parameter access, and continuous data recording in physics experiments, engineering tests, and system diagnostics.",
  "tag_hints": [
    "modular data acquisition",
    "high-speed digitizer",
    "EPICS control",
    "signal streaming",
    "multi-slot chassis",
    "experimental diagnostics"
  ],
  "actions": [
    {
      "action_name": "auto-get_sites",
      "description": "获取机箱中的采集站点或模块列表。",
      "description_en": "Get the list of acquisition sites or installed modules in the chassis."
    },
    {
      "action_name": "auto-int_statemon",
      "description": "启动设备内部状态监视。",
      "description_en": "Start internal status monitoring for the device."
    },
    {
      "action_name": "auto-caget",
      "description": "读取设备EPICS过程变量（PV）的当前值。",
      "description_en": "Read the current value of an EPICS process variable (PV) from the device."
    },
    {
      "action_name": "auto-caput",
      "description": "写入设备EPICS过程变量（PV）以设置参数或控制状态。",
      "description_en": "Write an EPICS process variable (PV) on the device to set a parameter or control a state."
    },
    {
      "action_name": "auto-monitor",
      "description": "监视指定过程变量（PV）的更新。",
      "description_en": "Monitor updates to a specified process variable (PV)."
    },
    {
      "action_name": "auto-clearpv",
      "description": "停止对指定过程变量（PV）的监视。",
      "description_en": "Stop monitoring a specified process variable (PV)."
    },
    {
      "action_name": "auto-readpv",
      "description": "读取指定过程变量（PV）的值。",
      "description_en": "Read the value of a specified process variable (PV)."
    },
    {
      "action_name": "auto-stream_to_disk",
      "description": "将采集数据连续流式保存到磁盘。",
      "description_en": "Continuously stream acquired data to disk."
    },
    {
      "action_name": "auto-stop_stream",
      "description": "停止数据流式保存。",
      "description_en": "Stop streaming data to disk."
    },
    {
      "action_name": "auto-pv_callback",
      "description": "处理过程变量（PV）更新时触发的回调。",
      "description_en": "Handle the callback triggered when a process variable (PV) updates."
    },
    {
      "action_name": "auto-clean",
      "description": "清理监视或采集过程中占用的资源。",
      "description_en": "Clean up resources used during monitoring or acquisition."
    }
  ]
}

